<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
if (isset($_SESSION['admin']) && time()-(int)($_SESSION['last_seen']??0)>1800) unset($_SESSION['admin']);
if (empty($_SESSION['admin'])) { http_response_code(403); exit('Inicia sesión desde el panel de administración.'); }
$_SESSION['last_seen']=time();
$appRoot=dirname((new ReflectionFunction('db'))->getFileName());
require_once $appRoot.'/DatabaseMaintenance.php';
$maintenance=null;$report=null;$error='';$success='';$details=[];
try{$maintenance=new DatabaseMaintenance(db(),$appRoot,(string)($_SERVER['DOCUMENT_ROOT']??''));}
catch(PDOException $e){$error='No se pudo conectar a la base de datos. Revisa el archivo de configuración privado, el servidor y los permisos.';http_response_code(503);}
if($maintenance&&$_SERVER['REQUEST_METHOD']==='POST'){
    try{
        csrf();$action=(string)($_POST['action']??'');$confirmation=is_string($_POST['confirmation']??null)?trim($_POST['confirmation']):'';
        if($action==='install'&&hash_equals('CREAR ESQUEMA',$confirmation)){$maintenance->installBaseSchema();$success='Esquema base instalado. Revisa el estado y aplica las migraciones pendientes.';}
        elseif($action==='migrate'&&($_POST['confirm_migrations']??'')==='1'){$details=$maintenance->applyMigrations();$success='La estructura pendiente quedó preparada. Recarga las secciones que estaban fallando.';}
        elseif($action==='import'&&hash_equals('IMPORTAR DESTINOS',$confirmation)){$details=$maintenance->importInitialCatalog();$success='Catálogo inicial importado. Los estados de publicación provienen del catálogo aprobado.';}
        else throw new RuntimeException('Acción o confirmación no válida. No se hicieron cambios.');
    }catch(PDOException $e){$error='La base rechazó la operación. Revisa permisos y el esquema; vuelve a cargar esta página para ver el estado real.';http_response_code(400);}
    catch(Throwable $e){$error=$e->getMessage();http_response_code(400);}
}
if($maintenance){try{$report=$maintenance->inspect();}
catch(PDOException $e){$report=null;$error=$error?:'No se pudo consultar el estado de la base de datos. Revisa la configuración privada y los permisos.';http_response_code(503);}}
function db_state_label(?string $state):string{return match($state){'applied'=>'Lista','pending'=>'Pendiente','partial'=>'Requiere revisión',default=>'No disponible'};}
function db_migration_label(string $id):string{return match($id){'001-phone-type','002-participation-version'=>'Campos del formulario de contacto','003-dynamic-destinations'=>'Destinos, atractivos y catálogo de negocios','004-media-origin','007-media-provenance'=>'Origen y trazabilidad privada de imágenes','005-destination-internal-research'=>'Investigación interna de destinos','006-poi-experience-links'=>'Enlaces de atractivos y experiencias','008-business-subscriptions'=>'Suscripciones y niveles de negocio','009-business-origin'=>'Origen de los negocios','010-business-location-subscription-lifecycle'=>'Ubicación, vigencia y ciclo de suscripción','011-premium-business-story'=>'Contenido ampliado de negocio','012-business-image-references'=>'Referencias privadas de imágenes para negocios','013-accounts-location-map'=>'Cuentas empresariales y permisos','014-tiered-business-description','015-business-media-quotas','016-plan-content-limits'=>'Límites y capacidades por suscripción','017-business-claims','018-business-portal'=>'Solicitudes para representar negocios','019-business-account-applications'=>'Registro y solicitudes de cuentas empresariales','020-account-password-resets'=>'Enlaces temporales para crear o cambiar contraseñas','021-business-payment-evidence'=>'Comprobantes privados de pago de suscripciones','022-subscription-prices'=>'Tarifas mensuales y anuales acordadas','023-business-representation-evidence'=>'Documentos privados para verificar representación','024-payment-customer-message'=>'Respuesta de pagos visible para el negocio','025-subscription-renewal-history'=>'Historial de renovaciones para medir retención','026-business-research-contacts'=>'Canales privados y sus fuentes','027-business-bulk-update-audit'=>'Historial de actualización masiva','028-accounts-business-channels'=>'Cuenta responsable y destinatarios de canales','029-business-email-campaigns'=>'Campañas por correo con Brevo',default=>$id};}
function db_table_label(string $table):string{return ['leads'=>'Solicitudes de contacto','destinations'=>'Destinos','businesses'=>'Negocios','media_assets'=>'Imágenes del portal','business_image_references'=>'Referencias de imágenes privadas','business_claim_requests'=>'Solicitudes para representar negocios','business_account_applications'=>'Solicitudes de cuenta empresarial','business_account_application_evidence'=>'Documentos de representación (privados)','account_password_resets'=>'Enlaces de contraseña (datos privados)','business_subscription_payment_evidence'=>'Comprobantes de pago (privados)'][$table]??$table;}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Estado de la base de datos | Explorando Lugares</title><link rel="stylesheet" href="../assets/style.css?v=admin-navigation-20261015"><link rel="stylesheet" href="../assets/admin.css?v=admin-workflow-20261015-2"></head><body><main class="wrap admin-page"><a class="brand" href="../index.html"><img class="brand-logo" src="../assets/logo.svg" alt="" width="64" height="64"><span>Explorando<b>Lugares</b></span></a><h1>Estado de la base de datos</h1><p>Esta sección es técnica y no hace parte del trabajo diario. Sirve para comprobar la conexión y preparar las tablas que necesita una versión nueva del portal. No permite escribir consultas ni borrar registros.</p>
<?php require __DIR__.'/_navigation.php'; ?>
<?php if($error!==''):?><div class="notice" role="alert"><?=esc($error)?></div><?php endif?><?php if($success!==''):?><div class="notice" role="status"><?=esc($success)?></div><?php endif?><?php if($details):?><ul><?php foreach($details as $key=>$value):?><li><code><?=esc($key)?></code> · <?=esc(is_scalar($value)?(string)$value:'Completado')?></li><?php endforeach?></ul><?php endif?>
<?php if(is_array($report)):?><section class="admin-system"><h2>Estado actual</h2><dl><dt>Conexión</dt><dd><?=esc($report['connected']?'Conectada':'No disponible')?></dd><dt>Motor</dt><dd><?=esc($report['driver'])?></dd><dt>Tablas</dt><dd><?=esc($report['tables'])?></dd><?php foreach($report['counts'] as $table=>$count):?><dt><?=esc(db_table_label($table))?></dt><dd><?=$count===null?'Tabla aún no creada':esc($count).' registros'?></dd><?php endforeach?></dl><h3>Componentes requeridos y su estado</h3><ul><?php foreach($report['migrations'] as $id=>$state):?><li><?=esc(db_migration_label($id))?> · <strong><?=esc(db_state_label($state))?></strong></li><?php endforeach?></ul></section>
<section class="admin-system"><h2>Aplicar cambios faltantes a la base de datos</h2><p>Esta acción agrega únicamente las tablas y campos que todavía no existen para la versión actual. No elimina negocios, solicitudes ni cuentas. Si todos los componentes aparecen listos, no necesitas ejecutarla.</p>
<?php if($report['empty_database']):?><form method="post" class="admin-db-action"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="install"><label>Confirmación<input name="confirmation" required autocomplete="off" placeholder="CREAR ESQUEMA"></label><button class="pill">Crear la estructura inicial</button><small>Solo aparece para una base completamente vacía. No aplica a la base que ya contiene datos.</small></form><?php endif?>
<?php if($report['base_schema']):?><form method="post" class="admin-db-action"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="migrate"><label class="admin-checkbox-field"><span>Confirmo aplicar únicamente los cambios de estructura que aparecen como pendientes arriba.</span><input type="checkbox" name="confirm_migrations" value="1" required></label><button class="pill compact">Aplicar cambios de estructura pendientes</button><small>La operación revisa el estado actual antes de cambiar la base de datos.</small></form><?php endif?>
<?php if($report['catalog_empty']&&$report['driver']==='mysql'):?><form method="post" class="admin-db-action"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="import"><label>Confirmación<input name="confirmation" required autocomplete="off" placeholder="IMPORTAR DESTINOS"></label><button class="pill">Importar catálogo inicial</button><small>Solo se ejecuta si destinos, categorías, negocios e imágenes están vacíos. Nunca reemplaza registros existentes.</small></form><?php endif?>
<p class="notice"><strong>Las migraciones agregan estructura sin borrar tablas ni modificar solicitudes existentes.</strong> La importación del catálogo semilla solo admite una base de catálogo vacía.</p></section><?php else:?><section class="admin-system"><h2>Sin conexión</h2><p>La página no muestra contraseñas ni detalles privados. Revisa el archivo de configuración privado y vuelve a cargar.</p></section><?php endif?>
<p><a class="text-link" href="index.php">Volver a solicitudes</a></p><script src="../assets/select-flotante.js" defer></script></main></body></html>
